for(const message of ["failed to request device code: error sending request for url (https://evil.invalid/api/accounts/deviceauth/usercode)","failed to request device code: error sending request for url (https://auth.openai.com/api/accounts/deviceauth/usercode) token=SECRET","failed to request device code: Failed to read CA certificate file /private/ca.pem selected by OTHER_VARIABLE: permission denied","prefix failed to request device code: Failed to build HTTP client while using system root certificates: client error"])test("near-match transport and CA failures remain generic",async()=>{const error=await classifyMessage(message);assert.equal(error.reason,"device_auth_internal");assert.doesNotMatch(JSON.stringify(error),/evil|SECRET|private|client error/)})

