// Test Codex uses a deterministic fake transport; no test contacts OpenAI.
import {access} from "node:fs/promises";
const assertEventuallyMissing=async path=>{const timeout=Date.now()+2_000;for(;;){try{await access(path)}catch{return}if(Date.now()>=timeout)assert.fail(`temporary path was not removed: ${path}`);await new Promise(resolve=>setImmediate(resolve))}};
import testSchemaFixture from "./fixtures/codex-0.153-test-schemas.json" with {type:"json"};
function healthFake(mode="success",requestId="approval-1"){
 const child=Object.assign(new EventEmitter(),{stdin:new PassThrough(),stdout:new PassThrough(),stderr:new PassThrough(),killed:false,kill(){this.killed=true}}),requests=[],cwds=[];
 const send=value=>child.stdout.write(`${JSON.stringify(value)}\n`);
 child.stdin.on("data",chunk=>{
  for(const line of chunk.toString().trim().split("\n")){
   if(!line)continue;
   const message=JSON.parse(line);requests.push(message);
   if(!message.id)continue;
   if(message.method==="initialize")send({id:message.id,result:{}});
   else if(message.method==="account/read"){if(mode==="account_failure")send({id:message.id,error:{code:-32603,message:"private raw error"}});else if(mode==="slow_account")setTimeout(()=>send({id:message.id,result:{account:{type:"chatgpt"}}}),200);else if(mode==="staged")setTimeout(()=>send({id:message.id,result:{account:{type:"chatgpt"}}}),30);else send({id:message.id,result:{account:{type:"chatgpt"}}})}
   else if(message.method==="thread/start"){
    cwds.push(message.params.cwd);
    if(mode==="thread_failure")send({id:message.id,error:{code:-32603,message:"private raw error"}});else if(mode==="staged")setTimeout(()=>send({id:message.id,result:{thread:{id:"thread-secret"}}}),30);else send({id:message.id,result:mode==="bad_thread"?{}:{thread:{id:"thread-secret"}}});
   }else if(message.method==="turn/start"){
    const nonce=message.params.input[0].text.match(/ADT_CODEX_TEST_[a-f0-9]+/)?.[0];
    if(mode==="turn_failure")send({id:message.id,error:{code:-32603,message:"private raw error"}});
    else if(mode==="bad_turn")send({id:message.id,result:{}});
    else if(mode==="approval"||mode==="collision"||mode==="string_request"){
     send({id:mode==="collision"?message.id:requestId,method:"item/commandExecution/requestApproval",params:{threadId:"thread-secret",turnId:"turn-secret",itemId:"item-secret"}});
     setImmediate(()=>send({id:message.id,result:{turn:{id:"turn-secret"}}}));
    }else{
     if(mode==="staged")setTimeout(()=>send({id:message.id,result:{turn:{id:"turn-secret"}}}),30);else send({id:message.id,result:{turn:{id:"turn-secret"}}});
     setImmediate(()=>{
      if(mode==="pending"||mode==="timeout"||mode==="hang_interrupt"||mode==="staged")return;
      if(mode==="tool")send({method:"item/started",params:{threadId:"thread-secret",turnId:"turn-secret",item:{type:"fileChange"}}});
      else{send({method:"item/completed",params:{threadId:"thread-secret",turnId:"turn-secret",item:{type:"agentMessage",text:mode==="wrong"?"wrong":nonce}}});send({method:"turn/completed",params:{threadId:"thread-secret",turn:{id:"turn-secret",status:mode==="failed"?"failed":"completed"}}})}
     });
    }
   }else if(message.method==="turn/interrupt"&&mode!=="hang_interrupt")send({id:message.id,result:{}});
  }
 });
 const release=()=>{const turn=requests.filter(x=>x.method==="turn/start").at(-1),nonce=turn?.params.input[0].text.match(/ADT_CODEX_TEST_[a-f0-9]+/)?.[0];send({method:"item/completed",params:{threadId:"thread-secret",turnId:"turn-secret",item:{type:"agentMessage",text:nonce}}});send({method:"turn/completed",params:{threadId:"thread-secret",turn:{id:"turn-secret",status:"completed"}}})};
 return{child,requests,cwds,release};
}
async function healthRun(mode,requestId,healthTimeout=100,cleanupReserve=10,requestTimeout=500){const fake=healthFake(mode,requestId),client=new StdioAppServerClient("codex","test",requestTimeout,()=>fake.child,healthTimeout,cleanupReserve),result=await client.testCodex();return{...fake,result}}
test("schema primitive type checks safely follow local references and combinators",()=>{
 const document={filename:"types.json",schema:{definitions:{Effort:{type:"string"},NumberEffort:{type:"number"},CycleA:{$ref:"#/definitions/CycleB"},CycleB:{$ref:"#/definitions/CycleA"}}}};
 const referenced=name=>({anyOf:[{$ref:`#/definitions/${name}`},{type:"null"}]});
 assert.equal(schemaAcceptsType(document,referenced("Effort"),"string"),true);
 assert.equal(schemaAcceptsType(document,{type:["string","null"]},"string"),true);
 assert.equal(schemaAcceptsType(document,{oneOf:[{type:"null"},{type:"string"}]},"string"),true);
 assert.equal(schemaAcceptsType(document,{allOf:[{$ref:"#/definitions/Effort"}]},"string"),true);
 assert.equal(schemaAcceptsType(document,referenced("Missing"),"string"),false);
 assert.equal(schemaAcceptsType(document,referenced("NumberEffort"),"string"),false);
 assert.equal(schemaAcceptsType(document,referenced("CycleA"),"string"),false);
 assert.equal(schemaAcceptsType(document,{properties:{unrelated:{type:"string"}}},"string"),false);
});
