for(const[mode,reason]of[["account_failure","app_server_unavailable"],["thread_failure","thread_start_failed"],["bad_thread","thread_start_failed"],["turn_failure","turn_start_failed"],["bad_turn","turn_start_failed"],["failed","turn_failed"],["wrong","unexpected_output"],["tool","unexpected_tool_activity"],["approval","unexpected_tool_activity"]])test(`health tester bounds ${mode} as ${reason}`,async()=>{const run=await healthRun(mode);assert.deepEqual(run.result,{ok:false,reason});assert.ok(run.requests.filter(x=>x.method==="thread/start").length<=1);assert.ok(run.requests.filter(x=>x.method==="turn/start").length<=1);for(const cwd of run.cwds)await assertEventuallyMissing(cwd);assert.doesNotMatch(JSON.stringify(run.result),/secret|ADT_CODEX_TEST|raw/)});
