test("setup phases consume the shared deadline and leave only the remainder for the model",async()=>{const started=Date.now(),run=await healthRun("staged",undefined,200,60),elapsed=Date.now()-started;assert.deepEqual(run.result,{ok:false,reason:"timeout"});assert.equal(run.requests.filter(x=>x.method==="thread/start").length,1);assert.equal(run.requests.filter(x=>x.method==="turn/start").length,1);assert.equal(run.requests.filter(x=>x.method==="turn/interrupt").length,1);assert.ok(elapsed>=120&&elapsed<300);for(const cwd of run.cwds)await assertEventuallyMissing(cwd)});
test("a hanging interrupt cannot extend the outward absolute deadline",async()=>{const started=Date.now(),run=await healthRun("hang_interrupt",undefined,100,30),elapsed=Date.now()-started;assert.deepEqual(run.result,{ok:false,reason:"timeout"});assert.equal(run.requests.filter(x=>x.method==="turn/interrupt").length,1);assert.ok(elapsed<200);for(const cwd of run.cwds)await assertEventuallyMissing(cwd)});

test("App Server stderr diagnostics are bounded and redact credential classes",()=>{const safe=sanitizeAppServerStderr("Authorization: Bearer top-secret api_key=sk-test password=hunter2 https://name:pass@proxy.example/path"+"x".repeat(1000));assert.ok(safe.length<=512);assert.doesNotMatch(safe,/top-secret|sk-test|hunter2|name:pass/);assert.match(safe,/REDACTED/)})

test("executor sqlite_home CLI override wins without entering workflow shell environment",()=>{const environment={CODEX_SQLITE_HOME:"/data/codex-sqlite",HOME:"/home/node"};assert.equal(executorCodexConfigOverrides(environment)[0],'sqlite_home="/data/codex-sqlite"');assert.equal(executorShellEnvironment(environment).CODEX_SQLITE_HOME,undefined)});

test("closeAndWait does not resolve until delayed App Server exit",async()=>{const input=new PassThrough(),output=new PassThrough(),stderr=new PassThrough(),child=Object.assign(new EventEmitter(),{stdin:input,stdout:output,stderr,killed:false,exitCode:null,kill(){this.killed=true;setTimeout(()=>{this.exitCode=0;this.emit("exit",0);this.emit("close",0)},30)}});input.on("data",chunk=>{for(const line of chunk.toString().trim().split("\n")){const message=JSON.parse(line);if(message.id)output.write(`${JSON.stringify({id:message.id,result:{}})}\n`)}});const client=new StdioAppServerClient("codex","test",100,()=>child);assert.equal(await client.readiness(),true);let closed=false;const closing=client.closeAndWait().then(()=>{closed=true});await new Promise(resolve=>setTimeout(resolve,10));assert.equal(closed,false);await closing;assert.equal(closed,true)});

test("startup diagnostics preserve terminal root causes and explicit diagnostics propagate",async()=>{const spawnFailure=new StdioAppServerClient("codex","test",10,()=>{throw new Error("spawn")});assert.equal(await spawnFailure.readiness(),false);assert.equal(spawnFailure.startupDiagnostic().category,"spawn_failed");const timeoutChild=Object.assign(new EventEmitter(),{stdin:new PassThrough(),stdout:new PassThrough(),stderr:new PassThrough(),killed:false,exitCode:null,kill(){this.killed=true;this.exitCode=0;this.emit("exit",0)}}),timeoutClient=new StdioAppServerClient("codex","test",10,()=>timeoutChild);assert.equal(await timeoutClient.readiness(),false);assert.equal(timeoutClient.startupDiagnostic().category,"initialize_timeout");const diagnostic={category:"process_exited",elapsedMs:12,exitCode:1,signal:"SIGTERM",stderrTail:["safe"]},result=await diagnoseAuthEnvironment({...offlineDiagnostics,appServerStartup:()=>diagnostic,codexAppServerReady:async()=>false});assert.deepEqual(result.appServerStartup,diagnostic)});

test("stderr sanitizer removes plain, JSON, mixed-case, bearer, and URL credentials",()=>{const secrets=["plain-one","json-two","bearer-three","pass-four","url-user","url-pass"];const input='token=plain-one {"Access_Token":"json-two"} bEaReR bearer-three PASSWORD:pass-four https://url-user:url-pass@proxy.example/path credential = final-five';const safe=sanitizeAppServerStderr(input);for(const secret of [...secrets,"final-five"])assert.doesNotMatch(safe,new RegExp(secret));assert.ok(safe.length<=512)});

test("every advertised startup category is bounded and first-terminal-root-cause wins",()=>{const categories=["ready","spawn_failed","process_exited","initialize_timeout","initialize_rpc_error","stdin_failure","stdout_closed"];for(const category of categories){const initial={category:"unknown",elapsedMs:0,stderrTail:[]},classified=preserveStartupDiagnostic(initial,category,12);assert.equal(classified.category,category);assert.equal(preserveStartupDiagnostic(classified,"initialize_rpc_error",20),classified)}})

async function shutdownClient(mode){const input=new PassThrough(),output=new PassThrough(),stderr=new PassThrough(),signals=[],child=Object.assign(new EventEmitter(),{stdin:input,stdout:output,stderr,killed:false,exitCode:null,kill(signal){signals.push(signal);this.killed=true;const finish=()=>{this.exitCode=0;this.emit("exit",0,signal);this.emit("close",0,signal)};if(mode==="immediate"&&signal==="SIGTERM")finish();if(mode==="delayed"&&signal==="SIGTERM")setTimeout(finish,8);if(mode==="kill"&&signal==="SIGKILL")finish();return true}});input.on("data",chunk=>{for(const line of chunk.toString().trim().split("\n")){const message=JSON.parse(line);if(message.id)output.write(`${JSON.stringify({id:message.id,result:{}})}\n`)}});const client=new StdioAppServerClient("codex","test",100,()=>child,100,10,[],12,12);assert.equal(await client.readiness(),true);return{client,signals}}
for(const mode of ["immediate","delayed","kill"])test(`closeAndWait confirms ${mode} App Server termination`,async()=>{const {client,signals}=await shutdownClient(mode);await client.closeAndWait();assert.equal(signals[0],"SIGTERM");assert.equal(signals.includes("SIGKILL"),mode==="kill")});
test("closeAndWait rejects when termination is never observed",async()=>{const {client,signals}=await shutdownClient("never");await assert.rejects(client.closeAndWait(),/app_server_shutdown_unconfirmed/);assert.deepEqual(signals,["SIGTERM","SIGKILL"])});

test("storage mutations use their dedicated timeout and ambiguous transport is explicit",async()=>{const {RemoteExecutorClient,ExecutorTransportError}=await import("../dist/executor.js"),original=globalThis.fetch,generation="123e4567-e89b-42d3-a456-426614174000",backup={backupId:"b-20260909T010203Z-abcdef123456",createdAt:"2026-09-09T01:02:03.000Z",runnerVersion:"a".repeat(40),codexVersion:"0.153.4",databases:[{filename:"state.sqlite",size:42,sha256:"b".repeat(64)}]},storage={separateSqliteHomeConfigured:true,sqliteFilesystemClass:"local",sqliteHomeReadable:true,sqliteHomeWritable:true,codexHomeFilesystemClass:"network",backupDirectoryAvailable:true,backupDirectoryWritable:true,retainedBackupCount:1,retention:14,operation:"idle"};try{globalThis.fetch=async(url,init)=>{await new Promise((resolve,reject)=>{const timer=setTimeout(resolve,20);init.signal.addEventListener("abort",()=>{clearTimeout(timer);reject(new Error("aborted"))},{once:true})});return Response.json({generation,backup})};const {generateKeyPairSync}=await import("node:crypto"),key=generateKeyPairSync("ed25519").privateKey.export({type:"pkcs8",format:"pem"}).toString(),client=new RemoteExecutorClient("http://executor.invalid",key,undefined,{requestMs:5,storageMs:50});assert.equal((await client.createSqliteBackup()).backupId,backup.backupId);await assert.rejects(client.sqliteStorage(),error=>error instanceof ExecutorTransportError);let calls=0;globalThis.fetch=async(_url,init)=>{calls++;if(init.method==="POST")throw new Error("connection lost");return Response.json({generation,status:storage,backups:[backup]})};await assert.rejects(client.restoreSqliteBackup(backup.backupId),error=>error.code==="storage_operation_result_unknown");assert.equal(calls,2)}finally{globalThis.fetch=original}});

test("storage timeout hierarchy leaves bounded transport margin",async()=>{const {EXECUTOR_STORAGE_OPERATION_TIMEOUT_MS}=await import("../dist/executor.js"),{CONTROLLER_STORAGE_OPERATION_TIMEOUT_MS}=await import("../dist/server.js");assert.ok(EXECUTOR_STORAGE_OPERATION_TIMEOUT_MS<CONTROLLER_STORAGE_OPERATION_TIMEOUT_MS);assert.ok(CONTROLLER_STORAGE_OPERATION_TIMEOUT_MS<120_000)});

test("stderr sanitizer removes ANSI and terminal control sequences",()=>{const safe=sanitizeAppServerStderr("\u001b[31merror\u001b[0m\u0007 token=private");assert.equal(safe,"error token=[REDACTED]");assert.doesNotMatch(safe,/\u001b|\u0007|private/)});
test("passive diagnostics report an absent creatable backup root as not initialized without mutation",async()=>{const accessed=[];const result=await diagnoseAuthEnvironment({...offlineDiagnostics,environment:{CODEX_HOME:"/private/home"},accessPath:async(path,mode)=>{accessed.push([path,mode])},statPath:async path=>{if(path.endsWith("/.adt/sqlite-backups"))throw Object.assign(new Error("missing"),{code:"ENOENT"});return{isFile:()=>true,size:10}},readSystemFile:async()=>"0"});assert.equal(result.storage.backupDirectoryState,"not_initialized");assert.equal(result.storage.backupDirectoryReadable,false);assert.ok(accessed.some(([path])=>path.endsWith("/.adt")));assert.equal(accessed.some(([path])=>path.endsWith("/.adt/sqlite-backups")),false)});


function workflowFake(mode){const input=new PassThrough(),output=new PassThrough(),stderr=new PassThrough(),requests=[],child=Object.assign(new EventEmitter(),{stdin:input,stdout:output,stderr,killed:false,kill(){this.killed=true;this.emit("exit",0)}}),send=value=>output.write(JSON.stringify(value)+"\n"),activity=(delay,threadId="thread-one",turnId="turn-one")=>setTimeout(()=>{send({method:"item/started",params:{threadId,...(turnId?{turnId}:{}),item:{type:"reasoning"}}});if(turnId){send({method:"item/completed",params:{threadId,turnId,item:{type:"agentMessage",text:"finished"}}});send({method:"turn/completed",params:{threadId,turn:{id:turnId,status:"completed"}}})}},delay);input.on("data",chunk=>{for(const line of chunk.toString().trim().split("\n")){const message=JSON.parse(line);requests.push(message);if(message.method==="initialize")send({id:message.id,result:{}});else if(message.method==="thread/start")send({id:message.id,result:{thread:{id:"thread-one"}}});else if(message.method==="turn/start"){if(mode==="reject")send({id:message.id,error:{code:-32000,message:"rejected"}});if(mode==="fast"){setTimeout(()=>send({id:message.id,result:{turn:{id:"turn-one"}}}),1);activity(5)}if(mode==="timeout_notification")activity(15);if(mode==="late"){setTimeout(()=>send({id:message.id,result:{turn:{id:"turn-one"}}}),18);activity(25)}if(mode==="activity"){activity(2);setTimeout(()=>send({id:message.id,result:{turn:{id:"turn-one"}}}),20)}if(mode==="thread_only"){activity(2,"thread-one",null);setTimeout(()=>send({id:message.id,result:{turn:{id:"turn-one"}}}),15);activity(20)}if(mode==="invalid"){send({id:message.id,result:{turn:{}}});activity(15)}}}});return{child,requests,output}}
async function workflowRun(mode){const fake=workflowFake(mode),events=[],client=new StdioAppServerClient("codex","test",10,()=>fake.child,100,10,[],20,20,40),result=await client.runWorkflowTurn({cwd:"/private/workspace",sandbox:"workspace-write",prompt:"TOP SECRET PROMPT",onLifecycle:event=>events.push(event)});return{fake,events,client,result}}
for(const mode of ["fast","timeout_notification","late","activity","thread_only","invalid"])test(`workflow ${mode} reconciles only authoritative turn identity without replay`,async()=>{const run=await workflowRun(mode);assert.deepEqual(run.result,{ok:true,outputText:"finished",threadId:"thread-one",turnId:"turn-one"});assert.equal(run.fake.requests.filter(x=>x.method==="thread/start").length,1);assert.equal(run.fake.requests.filter(x=>x.method==="turn/start").length,1);assert.equal(run.events.some(x=>x.event==="turn_start_ambiguous"),["timeout_notification","late","thread_only","invalid"].includes(mode));assert.doesNotMatch(JSON.stringify(run.events),/TOP SECRET|workspace|prompt|cwd/);if(mode==="late")assert.ok(run.events.findIndex(x=>x.event==="turn_start_reconciled")<run.events.findIndex(x=>x.event==="turn_started"));await run.client.close()});
test("definite rejection and unresolved ambiguity remain distinct without replay",async()=>{for(const [mode,reason] of [["reject","turn_start_failed"],["silent","turn_start_ambiguous"]]){const fake=workflowFake(mode),client=new StdioAppServerClient("codex","test",5,()=>fake.child,100,10,[],20,20,10),result=await client.runWorkflowTurn({cwd:"/private",sandbox:"workspace-write",prompt:"secret"});assert.equal(result.ok,false);assert.equal(result.reason,reason);assert.equal(fake.requests.filter(x=>x.method==="turn/start").length,1);await client.close()}});
test("wrong-thread activity cannot reconcile an ambiguous start",async()=>{const fake=workflowFake("silent"),client=new StdioAppServerClient("codex","test",5,()=>fake.child,100,10,[],20,20,15),running=client.runWorkflowTurn({cwd:"/private",sandbox:"workspace-write",prompt:"secret"});setTimeout(()=>fake.output.write(JSON.stringify({method:"turn/completed",params:{threadId:"other",turn:{id:"turn-other",status:"completed"}}})+"\n"),8);assert.equal((await running).reason,"turn_start_ambiguous");assert.equal(fake.requests.filter(x=>x.method==="turn/start").length,1);await client.close()});

test("managed split turns use full access inside the executor container",async()=>{const fake=workflowFake("fast"),overrides=executorCodexConfigOverrides({PATH:"/usr/bin:/bin",CODEX_SQLITE_HOME:"/data/codex-sqlite"}),client=new StdioAppServerClient("codex","test",10,()=>fake.child,100,10,overrides,20,20,40);const result=await client.runWorkflowTurn({cwd:"/workspaces/task",sandbox:"workspace-write",managedTaskId:"new-task",expectedManagedBranch:"adt/codex/previous-task",prompt:"local edit"});assert.equal(result.ok,true);const thread=fake.requests.find(value=>value.method==="thread/start");assert.equal(thread.params.sandbox,"danger-full-access");assert.equal("permissions" in thread.params,false);assert.equal(overrides.some(value=>value.includes("adt-managed")),false);await client.close()});
